                out.append(f"REQUEST {i} {r['code']['coding'][0]['code']} focus={r.get('focus',{}).get('reference')} : {r['description']}")
            else:
                out.append(f"ITEM {i} {r['code']['coding'][0]['code'] if 'code' in r else ''} {r.get('businessStatus',{}).get('text')}")
        else:
            out.append(t+' '+i)
    # specimens/obs in other charts referencing this patient's identifiers
    for s in res['Specimen']:
