            accs=[s for s in res['Specimen'] if s['accessionIdentifier']['value']==ext(b,'accession')]
            if any(sub(s)==pid for s in accs): continue
            out.append(f"[FOREIGN ACCESSION] {b['id']} acc={ext(b,'accession')} [{ext(b,'patient-name')}|{ext(b,'patient-mrn')}|{ext(b,'patient-dob')}] specimens_in={[(s['id'],sub(s)) for s in accs]}")
    return '\n'.join(out)
if __name__=='__main__':
    ids=sys.argv[1:] or sorted(pats)
