            notes='; '.join(n['text'] for n in r.get('note',[]))
            out.append(f"MEDADMIN {i} {r.get('effectiveDateTime','')[:10]} {r['status']} '{r['medicationCodeableConcept']['text']}' {r.get('dosage',{}).get('text')} by {r.get('performer',[{}])[0].get('actor',{}).get('display')} {notes}")
