            out.append(f"MEDDISP {i} {r.get('whenHandedOver','')[:10]} '{r['medicationCodeableConcept']['text']}' qty={r.get('quantity',{}).get('value')} days={r.get('daysSupply',{}).get('value')} sig={'; '.join(x.get('text','') for x in r.get('dosageInstruction',[]))} {'; '.join(n['text'] for n in r.get('note',[]))}")
        elif t=='DocumentReference':
            txt=r['description']
            if any(n in txt for n in NOISE): continue
            txt=re.sub(r'\n+(Electronically signed|Signed|Released by|Reviewed by|Authenticated by):.*','',txt).strip()
            out.append(f"DOC {i} {r.get('date','')[:10]} '{r['type']['text']}'/{ext(r,'author-role')} by {r.get('author',[{}])[0].get('display')}: "+txt.replace('\n',' | '))
        elif t=='Task' and r['status']=='requested':
            out.append(f"*** REQUEST {i} {r['code']['coding'][0]['code']} focus={r.get('focus',{}).get('reference')}: {r['description']}")
