    ep=d['EpisodeOfCare'][0]
    out.append(f"AUTO stage={stage} dx={ep['period']['start']} bpg_doses={doses}")
    out+= eng.followup(pid,stage,doses[0] if doses else None)
    # foreign: this patient's identity elsewhere
    for s in eng.res['Specimen']:
        if eng.sub(s)==pid: continue
        res_,cands,detail=eng.spec_identity(s)
        if pid in cands:
            o=eng.obs_by_spec.get(s['id'])
            out.append(f"FOREIGN spec {s['id']} in chart {eng.sub(s)} identity={res_ or sorted(cands)} coll={s['collection']['collectedDateTime'][:10]} obs={o['id'] if o else None} {o['code']['text'] if o else ''}={o.get('valueString') if o else ''}")
    return '\n'.join(out)
if __name__=='__main__':
    import sys
    for pid in (sys.argv[1:] or sorted(eng.pats)): print(render(pid)); print()
